package com.meetspace.repository; import com.meetspace.dto.EmployeeDtos.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository; import java.util.*;
@Repository public class EmployeeRepository{private final JdbcTemplate j;public EmployeeRepository(JdbcTemplate j){this.j=j;} public Optional<Profile> byUser(UUID user){return j.query("select e.id,e.employee_code,e.first_name,e.last_name,e.department,e.phone,u.email from employees e join users u on u.id=e.user_id where e.user_id=?",(r,n)->new Profile(UUID.fromString(r.getString("id")),r.getString("employee_code"),r.getString("first_name"),r.getString("last_name"),r.getString("department"),r.getString("phone"),r.getString("email")),user).stream().findFirst();} public java.util.List<Profile> all(){return j.query("select e.id,e.employee_code,e.first_name,e.last_name,e.department,e.phone,u.email from employees e join users u on u.id=e.user_id",(r,n)->new Profile(UUID.fromString(r.getString("id")),r.getString("employee_code"),r.getString("first_name"),r.getString("last_name"),r.getString("department"),r.getString("phone"),r.getString("email")));} public void update(UUID user,Update x){j.update("update employees set first_name=?,last_name=?,department=?,phone=? where user_id=?",x.firstName().trim(),x.lastName().trim(),x.department().trim(),blank(x.phone()),user);} private String blank(String v){return v==null||v.isBlank()?null:v.trim();}}